from collections import defaultdict

def transform_list_to_set(input_array, visited=None):
    if visited is None:
        visited = set()

    if id(input_array) in visited:
        return set()

    visited.add(id(input_array))

    if isinstance(input_array, list):
        return {list(transform_list_to_set(sub_list, visited)) for sub_list in input_array}
    elif isinstance(input_array, dict):
        return set([(key, transform_list_to_set(val, visited)) for key, val in input_array.items() if isinstance(val, list)])
